const body = $input.first().json.body;
const diffText = body.diffText || '';
const language = body.language || 'javascript';
const geminiKey = body.geminiApiKey;

const systemInstruction = `Bạn là Senior Principal Security & Code Reviewer.\nHãy phân tích đoạn git diff sau và trả về JSON thuần túy theo schema:\n{\n  "qualityScore": 85,\n  "grade": "B",\n  "summary": "Tóm tắt đánh giá chất lượng",\n  "issues": [\n    {\n      "id": "iss_1",\n      "line": 14,\n      "type": "SECURITY",\n      "severity": "CRITICAL",\n      "message": "Lỗ hổng SQL Injection phát hiện tại câu lệnh query",\n      "suggestion": "Sử dụng parameterized query thay vì nối chuỗi trực tiếp",\n      "refactoredCode": "db.query('SELECT * FROM users WHERE id = ?', [userId])"\n    }\n  ]\n}`;

return {
  json: {
    geminiKey,
    requestBody: {
      contents: [
        {
          role: "user",
          parts: [
            { text: `${systemInstruction}\n\nNGÔN NGỮ: ${language}\n\nGIT DIFF CẦN REVIEW:\n${diffText}` }
          ]
        }
      ],
      generationConfig: {
        temperature: 0.2,
        responseMimeType: "application/json"
      }
    }
  }
};

const response = $input.first().json;
let rawText = response.candidates[0].content.parts[0].text;
rawText = rawText.replace(/```json/gi, '').replace(/```/gi, '').trim();
const parsed = JSON.parse(rawText);

return {
  json: {
    success: true,
    data: parsed
  }
};
